      return [
        { "label": "À PERCEVOIR", "value": "À PERCEVOIR" },
        { "label": "CB", "value": "CB" },
        { "label": "Espèces", "value": "Espèces" },
        { "label": "Virement", "value": "Virement" },
        { "label": "Chèque", "value": "Chèque" }
      ];
